import{_ as r}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as e,o as a,ag as d}from"./chunks/mermaid.Bf0DxEx6.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const g=JSON.parse('{"title":"网易UU远程学习地图","description":"网易UU远程是网易出品的远程控制软件，走「画面串流」路线：两端装客户端，登录同一账号或报设备 ID 与验证码就能连。本页是产品全景加决策表，先回答「我该装哪个、什么时候用」，再进上手教程。","frontmatter":{"title":"网易UU远程学习地图","description":"网易UU远程是网易出品的远程控制软件，走「画面串流」路线：两端装客户端，登录同一账号或报设备 ID 与验证码就能连。本页是产品全景加决策表，先回答「我该装哪个、什么时候用」，再进上手教程。","domain":"product","tags":["remote-control","remote-desktop","netease"],"role":"map"},"headers":[],"relativePath":"zh/products/uu-remote/index.md","filePath":"zh/products/uu-remote/index.md","lastUpdated":1795792629000}'),l={name:"zh/products/uu-remote/index.md"};function o(h,t,n,s,u,i){return a(),e("div",null,[...t[0]||(t[0]=[d('<h1 id="网易uu远程学习地图" tabindex="-1">网易UU远程学习地图 <a class="header-anchor" href="#网易uu远程学习地图" aria-label="Permalink to &quot;网易UU远程学习地图&quot;">​</a></h1><blockquote><p><strong>网易UU远程</strong>（网易出品的远程控制软件）让你人在外面，也能操作自己的电脑，或帮别人修电脑。它走「画面串流」路线：两端装上客户端，登录同一个账号，或报「设备 ID + 验证码」，就能把另一台设备的桌面接到眼前。</p><p>本页是<strong>产品全景 + 决策表</strong>。装与用都在<a href="./uu-remote.html">上手教程</a>。界面文字与数字来自 2026-11-24 打开的网易官方页面。</p></blockquote><h2 id="写给谁-先决条件-非目标" tabindex="-1">写给谁 / 先决条件 / 非目标 <a class="header-anchor" href="#写给谁-先决条件-非目标" aria-label="Permalink to &quot;写给谁 / 先决条件 / 非目标&quot;">​</a></h2><ul><li><strong>写给谁</strong>：会写前端代码、用过命令行，但没接触过远程控制软件的人。</li><li><strong>先决条件</strong>：两台联网设备，一个网易UU远程账号。各平台的系统要求见教程的「安装」一节。</li><li><strong>非目标</strong>： <ul><li>不讲内部实现。官方没有公开建连流程、编解码器、协议和服务器架构。</li><li>不讲 UU加速器、MuMu模拟器、网易千千壁纸。它们只是官网「友情链接」里的产品。</li><li>不展开「云设备」（游戏云电脑、AI 云电脑）。它们是官网导航里另一组产品。</li><li>不对比其他远控软件的功能和价格。本页没有打开它们的官方页。</li></ul></li></ul><h2 id="产品家族" tabindex="-1">产品家族 <a class="header-anchor" href="#产品家族" aria-label="Permalink to &quot;产品家族&quot;">​</a></h2><p>下表「官方名称」抄自 2026-11-24 打开的官方页面。本目录<strong>只有一篇教程</strong>，其余各项占地图一行。</p><table tabindex="0"><thead><tr><th>官方名称</th><th>官方 URL</th><th>本站去向</th></tr></thead><tbody><tr><td><strong>Windows 版客户端</strong></td><td><a href="https://uuyc.163.com/download/" target="_blank" rel="noreferrer">下载页</a> · <a href="https://uuyc.163.com/" target="_blank" rel="noreferrer">官网首页</a></td><td>独立页：<a href="./uu-remote.html">上手教程</a></td></tr><tr><td><strong>macOS 版客户端</strong>（既能当主控，也能被控）</td><td>下载页 · <a href="https://uuyc.163.com/features/mac/" target="_blank" rel="noreferrer">远程控制 Mac 电脑</a> · <a href="https://uuyc.163.com/help/macos.html" target="_blank" rel="noreferrer">如何控制 Mac</a></td><td>教程一节：安装里让 Mac 可被控</td></tr><tr><td><strong>iOS 版客户端</strong>（App Store 名为「UU远程-流畅可靠，就是好用！」，卖方 Guangzhou NetEase Computer System Co.Ltd）</td><td><a href="https://apps.apple.com/cn/app/id1642306791" target="_blank" rel="noreferrer">App Store</a> · 下载页</td><td>教程一节：用手机控制电脑</td></tr><tr><td><strong>Android 版客户端</strong></td><td><a href="https://uuyc.163.com/download/" target="_blank" rel="noreferrer">下载页</a></td><td>教程一节：用手机控制电脑</td></tr><tr><td><strong>Android TV 版客户端</strong>（官网也叫「电视版」，只能当主控端，只能连 Windows）</td><td>下载页 · <a href="https://uuyc.163.com/features/tv/" target="_blank" rel="noreferrer">客厅电视畅玩</a> · <a href="https://uuyc.163.com/help/20250117/40220_1207352.html" target="_blank" rel="noreferrer">TV 端使用教程</a></td><td>地图一行</td></tr><tr><td><strong>UU远程精简版</strong>（远程协助的被控端，仅 Windows，免安装免登录）</td><td><a href="https://uuyc.163.com/features/sos/" target="_blank" rel="noreferrer">精简版页</a> · <a href="https://uuyc.163.com/help/green.html" target="_blank" rel="noreferrer">使用教程</a></td><td>教程一节：帮别人做远程协助</td></tr><tr><td><strong>UU远程运维版</strong>（机房批量部署，带命令行）</td><td><a href="https://uuyc.163.com/help/cmd.html" target="_blank" rel="noreferrer">命令行使用教程</a> · <a href="https://uuyc.163.com/help/ops.html" target="_blank" rel="noreferrer">制作教程</a></td><td>地图一行</td></tr><tr><td><strong>uuyc-cli</strong>（官方命令行工具）</td><td><a href="https://uuyc.163.com/help/cli.html" target="_blank" rel="noreferrer">CLI 教程</a></td><td>教程一节：官方 CLI</td></tr><tr><td><strong>VIP 会员、全球 VIP 会员</strong></td><td><a href="https://uuyc.163.com/help/membership.html" target="_blank" rel="noreferrer">会员权益详情</a> · <a href="https://uuyc.163.com/help/service-agreement.html" target="_blank" rel="noreferrer">会员服务协议</a></td><td>教程一节：费用</td></tr><tr><td><strong>UU远程 Linux PC 端</strong>（内测，主控与被控都支持）</td><td><a href="https://uuyc.163.com/help/linux_test.html" target="_blank" rel="noreferrer">Linux 内测常见问题</a></td><td>地图一行：内测中</td></tr><tr><td><strong>UU远程 HarmonyOS 移动端</strong>（内测，只能当主控端）</td><td><a href="https://uuyc.163.com/help/harmonyos_test.html" target="_blank" rel="noreferrer">HarmonyOS 内测常见问题</a></td><td>地图一行：内测中</td></tr><tr><td><strong>掌机</strong></td><td>官网首页定位文案提到「掌机」；下载页没有掌机客户端条目</td><td>地图一行：以官网为准</td></tr><tr><td><strong>云设备</strong>（游戏云电脑、AI 云电脑、云硬盘）</td><td>官网导航「云设备」分组 · <a href="https://uuyc.163.com/help/20260422/42867_1297276.html" target="_blank" rel="noreferrer">如何使用云硬盘</a></td><td>地图一行：不是本产品</td></tr></tbody></table><h3 id="容易撞名" tabindex="-1">容易撞名 <a class="header-anchor" href="#容易撞名" aria-label="Permalink to &quot;容易撞名&quot;">​</a></h3><ul><li><strong>UU远程 ≠ UU加速器。</strong> UU加速器是游戏加速器，在官网「友情链接」里，和本产品无关。容易混淆的一处：官方路由器文档里，让路由器给 UU远程 当「开机辅助设备」时，装的插件叫「网易UU加速器插件 WOL 版本」。</li><li><strong>UU远程 ≠ MuMu模拟器、网易千千壁纸。</strong> 同在友情链接里。</li><li><strong>「GameViewer远程」是旧名。</strong> 官方公告页（页面日期 2024-12-10）写明「GameViewer远程」正式更名为「网易UU远程」，见<a href="https://uuyc.163.com/blog/20241206/41377_1198665.html" target="_blank" rel="noreferrer">官方公告</a>。</li><li><strong>StarDesk 是海外版的名字。</strong> 同一套软件在海外以 StarDesk 名称发布，有自己的<a href="https://www.stardesk.net" target="_blank" rel="noreferrer">官网</a>和 <a href="https://apps.apple.com/us/app/id6751540294" target="_blank" rel="noreferrer">App Store 应用</a>（商店里登记的开发者是 GearUP Portal Pte. Ltd.，2025-09-28 上架）。国内版 Windows 客户端的英文界面文案也大多用这个名字。两版的官网、下载和定价各自独立，本目录只讲国内版。</li><li><strong>VIP ≠ 全球 VIP。</strong> 全球 VIP 多一项「全球远控节点」。官方常见问题写明，被控端在境外，或主控端开着 VPN 被识别为境外时，会提示开通全球 VIP。价格与权益见教程的「费用」一节。</li><li><strong>「安全密码」不是连接密码。</strong> 它给客户端上锁；连接靠验证码。</li><li><strong>「安卓屏幕共享」不是远程控制安卓手机。</strong> 对方只能看、听、批注，不能操控。</li></ul><h3 id="官方一级导航对账" tabindex="-1">官方一级导航对账 <a class="header-anchor" href="#官方一级导航对账" aria-label="Permalink to &quot;官方一级导航对账&quot;">​</a></h3><p>官网首页的两级导航如下，每一项都有去处。</p><table tabindex="0"><thead><tr><th>使用场景（官方名称）</th><th>官方 URL</th><th>一句话</th></tr></thead><tbody><tr><td>远程办公</td><td><a href="https://uuyc.163.com/features/work/" target="_blank" rel="noreferrer">features/work</a></td><td>开发、设计、剪辑时接回自己的工作站</td></tr><tr><td>远程游戏</td><td><a href="https://uuyc.163.com/games/" target="_blank" rel="noreferrer">games</a></td><td>用手机、平板、电视玩电脑游戏</td></tr><tr><td>远程协助</td><td><a href="https://uuyc.163.com/features/support/" target="_blank" rel="noreferrer">features/support</a></td><td>报设备 ID 和验证码，帮别人修电脑</td></tr><tr><td>客厅畅玩</td><td><a href="https://uuyc.163.com/features/tv/" target="_blank" rel="noreferrer">features/tv</a></td><td>电视版远控电脑</td></tr><tr><td>Mac 电脑被控</td><td><a href="https://uuyc.163.com/features/mac/" target="_blank" rel="noreferrer">features/mac</a></td><td>多端远控 Mac</td></tr></tbody></table><table tabindex="0"><thead><tr><th>特色功能（官方名称）</th><th>官方 URL</th><th>教程去处</th></tr></thead><tbody><tr><td>文件传输</td><td><a href="https://uuyc.163.com/features/file/" target="_blank" rel="noreferrer">features/file</a></td><td>传输文件、同步剪贴板、传声音</td></tr><tr><td>高清画面</td><td><a href="https://uuyc.163.com/features/color/" target="_blank" rel="noreferrer">features/color</a></td><td>调画质、帧率、分辨率</td></tr><tr><td>隐私防护</td><td><a href="https://uuyc.163.com/features/privacy/" target="_blank" rel="noreferrer">features/privacy</a></td><td>在会议室或公共场合开防窥</td></tr><tr><td>多屏协作</td><td><a href="https://uuyc.163.com/features/device/" target="_blank" rel="noreferrer">features/device</a></td><td>同时看多块屏或多台设备</td></tr><tr><td>远程开机</td><td><a href="https://uuyc.163.com/features/wol/" target="_blank" rel="noreferrer">features/wol</a></td><td>远程开机</td></tr><tr><td>按键映射</td><td><a href="https://uuyc.163.com/features/keyboard/" target="_blank" rel="noreferrer">features/keyboard</a></td><td>玩游戏</td></tr><tr><td>无线副屏</td><td><a href="https://uuyc.163.com/features/wireless-screen/" target="_blank" rel="noreferrer">features/wireless-screen</a></td><td>把平板或手机当无线副屏</td></tr></tbody></table><h2 id="它解决什么问题" tabindex="-1">它解决什么问题 <a class="header-anchor" href="#它解决什么问题" aria-label="Permalink to &quot;它解决什么问题&quot;">​</a></h2><h3 id="没有它-vs-有它" tabindex="-1">没有它 vs 有它 <a class="header-anchor" href="#没有它-vs-有它" aria-label="Permalink to &quot;没有它 vs 有它&quot;">​</a></h3><table tabindex="0"><thead><tr><th>场景</th><th>没有远程控制</th><th>用网易UU远程</th></tr></thead><tbody><tr><td>文件落在关机的家里电脑里</td><td>只能回去开机再取</td><td>远程开机后用文件传输取回（要事先配好唤醒条件）</td></tr><tr><td>父母的电脑出问题，你在外地</td><td>靠电话一步步描述</td><td>父母报设备 ID 和验证码，你直接操作</td></tr><tr><td>家里电脑在跑编译或 agent</td><td>人必须守着</td><td>手机上看进度、敲下一步；终端会话断开后可以重接</td></tr><tr><td>想在大屏上看电脑画面</td><td>把电脑搬到电视旁</td><td>用电视版远控，或把平板接成无线副屏</td></tr></tbody></table><h3 id="与替代方案对比" tabindex="-1">与替代方案对比 <a class="header-anchor" href="#与替代方案对比" aria-label="Permalink to &quot;与替代方案对比&quot;">​</a></h3><p>只列本页能核实的内容。</p><table tabindex="0"><thead><tr><th>方案</th><th>怎么连</th><th>适合谁</th><th>本站去向</th></tr></thead><tbody><tr><td>网易UU远程</td><td><strong>画面串流</strong>：两端装客户端，登录同一账号，或报设备 ID 与验证码</td><td>想装上就用，不想自己配网络的人</td><td>本目录</td></tr><tr><td>Tailscale 加系统自带远程桌面</td><td>先在<strong>网络层</strong>把设备组成一个私有网络，再用系统自带的远程桌面连过去</td><td>愿意自己配置、想用系统远程桌面的人</td><td><a href="./../tailscale/">Tailscale</a></td></tr><tr><td>Cindy</td><td>内置手机远程桌面功能</td><td>想在一个工具里同时处理手机侧操作的人</td><td><a href="./../cindy/">Cindy</a></td></tr><tr><td>其他远控软件（ToDesk、向日葵、RustDesk 等）</td><td>本页没有核对它们的官方页，不作对比</td><td>无</td><td>无</td></tr></tbody></table><h2 id="快速决策" tabindex="-1">快速决策 <a class="header-anchor" href="#快速决策" aria-label="Permalink to &quot;快速决策&quot;">​</a></h2><table tabindex="0"><thead><tr><th>我的情况</th><th>用什么</th></tr></thead><tbody><tr><td>帮同事或父母临时处理一次电脑问题</td><td>远程协助：对方报「设备 ID + 临时验证码」</td></tr><tr><td>对方没装客户端，也不想装</td><td>发<a href="https://uuyc.163.com/features/sos/" target="_blank" rel="noreferrer">UU远程精简版</a>，仅限 Windows 被控端</td></tr><tr><td>自己的电脑，想随时连</td><td>两端登录同一账号，主控端点[进入桌面]</td></tr><tr><td>自己的电脑关机了也想连</td><td>先配远程开机：网卡、主板、局域网辅助设备三样缺一不可</td></tr><tr><td>被控电脑是 Mac</td><td>先在 Mac 上开[允许本设备被控]和两项系统权限</td></tr><tr><td>在外面用手机看编码 agent 的进度</td><td>同账号远控，进[设备详情]-[终端]，或全屏桌面加小窗模式</td></tr><tr><td>只想取一个文件</td><td>同账号用[文件传输]入口；远程协助用拖拽或复制粘贴</td></tr><tr><td>在会议室或咖啡馆操作</td><td>开[被控端防窥模式]和[被控端自动锁屏]</td></tr><tr><td>公司或学校网络连不上</td><td>客户端[设置]-[网络]-[代理设置]（前提是已有可用代理）</td></tr><tr><td>想要 4K、144 帧、真彩、HDR、多屏控多屏</td><td>这些是 VIP 权益，官方公告写 2026-12-01 上线</td></tr><tr><td>想把安卓手机屏幕给别人看</td><td>安卓屏幕共享，只能看不能控</td></tr><tr><td>更想自己组网、少装一个远控客户端</td><td>看 <a href="./../tailscale/">Tailscale</a> 页</td></tr></tbody></table><h2 id="本目录怎么读" tabindex="-1">本目录怎么读 <a class="header-anchor" href="#本目录怎么读" aria-label="Permalink to &quot;本目录怎么读&quot;">​</a></h2><table tabindex="0"><thead><tr><th>顺序</th><th>读什么</th><th>目标</th></tr></thead><tbody><tr><td>1</td><td>教程「核心概念」</td><td>分得清主控端、被控端、设备 ID、验证码</td></tr><tr><td>2</td><td>教程「安装」与「10 分钟跑通第一件事」</td><td>用设备 ID 和验证码连上一次</td></tr><tr><td>3</td><td>教程「日常用法」</td><td>配无人值守、远程开机、文件传输、防窥</td></tr><tr><td>4</td><td>教程「费用」与「安全与隐私要点」</td><td>知道免费边界，知道什么不能给</td></tr><tr><td>5</td><td>教程「真实用例」</td><td>把家里的电脑当远程工作站</td></tr></tbody></table><p>先读核心概念再动手。跳过它直接连，你会在「开关配在哪一端」上卡住。</p><h2 id="官方资源" tabindex="-1">官方资源 <a class="header-anchor" href="#官方资源" aria-label="Permalink to &quot;官方资源&quot;">​</a></h2><ul><li><a href="https://uuyc.163.com/" target="_blank" rel="noreferrer">官网首页</a>：产品定位、特色功能入口、安全声明。</li><li><a href="https://uuyc.163.com/download/" target="_blank" rel="noreferrer">下载页</a>：五个客户端的系统要求和当前版本。</li><li><a href="https://uuyc.163.com/help/" target="_blank" rel="noreferrer">帮助中心</a>：全部功能指引与常见问题的目录。</li><li><a href="https://uuyc.163.com/features/support/" target="_blank" rel="noreferrer">远程协助功能页</a>：远程协助三步走，三种被控端平台。</li><li><a href="https://uuyc.163.com/help/20241204/40220_1197664.html" target="_blank" rel="noreferrer">如何远程协助他人电脑</a>：验证码、验证方式、收藏设备的最完整说明。</li><li><a href="https://uuyc.163.com/help/4.0wol.html" target="_blank" rel="noreferrer">如何设置远程开机</a>：唤醒条件和逐步配置。</li><li><a href="https://uuyc.163.com/help/20241210/40220_1199229.html" target="_blank" rel="noreferrer">如何进行文件传输</a>：三种传输方式各自适用在哪。</li><li><a href="https://uuyc.163.com/help/20241203_40221_1197692.html" target="_blank" rel="noreferrer">如何开启或关闭防窥模式</a>：两档防窥的区别。</li><li><a href="https://uuyc.163.com/help/errorcode.html" target="_blank" rel="noreferrer">错误码解决方法</a>：连不上、装不上时查。</li><li><a href="https://uuyc.163.com/help/membership.html" target="_blank" rel="noreferrer">会员权益详情</a>：免费版、VIP、全球 VIP 的权益对比。</li><li><a href="https://uuyc.163.com/bounty/" target="_blank" rel="noreferrer">赏金猎人计划</a>：官方漏洞报告与奖励渠道。</li><li><a href="https://uuyc.163.com/llms.txt" target="_blank" rel="noreferrer">llms.txt</a>：官方给 AI 和搜索引擎看的产品事实摘要，列全了官方页面入口。</li></ul><h2 id="相关页面" tabindex="-1">相关页面 <a class="header-anchor" href="#相关页面" aria-label="Permalink to &quot;相关页面&quot;">​</a></h2><ul><li><a href="./uu-remote.html">上手教程</a>：本目录唯一的教程页，从安装到日常用法。</li><li><a href="./../tailscale/">Tailscale</a>：对比「网络层打洞」与「画面串流」两种远程思路。</li><li><a href="./../cindy/">Cindy</a>：内置手机远程桌面功能。</li><li><a href="./../t3code/">T3 Code</a>：从手机批准 agent 的下一步。</li><li><a href="./../codex/">Codex</a>：在远端开发机上运行的编码 agent 之一。</li><li><a href="./../claude/">Claude</a>：同上。</li></ul>',28)])])}const b=r(l,[["render",o]]);export{g as __pageData,b as default};
